const DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
let data={tasks:[],rules:[],members:[]};
let rev={};
let today=null;
const $=id=>document.getElementById(id);
function parse(s){const p=s.split('-').map(Number);return Date.UTC(p[0],p[1]-1,p[2]);}
function fmt(ms){const d=new Date(ms);return d.getUTCFullYear()+'-'+String(d.getUTCMonth()+1).padStart(2,'0')+'-'+String(d.getUTCDate()).padStart(2,'0');}
function wd(ms){return new Date(ms).getUTCDay();}
function names(){const m=(data.members||[]).map(x=>x.name);return m.length?m:['Ana','Leo','Me'];}
function blocked(){return (data.rules||[]).map(r=>r.weekday);}
function buildSessions(){
 const out=[];if(!today)return out;
 const b=blocked();const t0=parse(today);
 for(const t of data.tasks||[]){
  let first=t0;while(wd(first)!==t.weekday)first+=86400000;
  for(let k=0;k<4;k++){
   let d=first+k*7*86400000;let n=0;
   while(b.includes(wd(d))&&n<7){d+=86400000;n++;}
   out.push({task:t,date:fmt(d)});
  }
 }
 out.sort((a,c)=>a.date<c.date?-1:a.date>c.date?1:0);
 return out;
}
function el(tag,text,cls){const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;}
function render(){
 const sl=$('sessions');sl.textContent='';
 const ss=buildSessions();
 $('status').textContent=ss.length?'':'Nothing planned yet. Add a chore above.';
 for(const s of ss){
  const li=el('li');li.setAttribute('data-hook','session');
  const left=el('span');
  const tm=el('time',fmt0(s.date));tm.setAttribute('datetime',s.date);
  left.appendChild(tm);left.appendChild(document.createTextNode(' · '));
  const nm=el('strong','');nm.textContent=s.task.name;nm.style.fontWeight='400';nm.setAttribute('data-hook','session-task');
  left.appendChild(nm);
  li.appendChild(left);li.appendChild(el('span','Who: '+s.task.assignee,'meta'));
  sl.appendChild(li);
 }
 const tl=$('tasks');tl.textContent='';
 for(const t of data.tasks||[]){
  const li=el('li');
  li.appendChild(el('span',t.name+' — '+t.assignee+', every '+DAYS[t.weekday]));
  const b=el('button','Remove','sec');b.type='button';b.setAttribute('aria-label','Remove chore '+t.name);
  b.addEventListener('click',()=>removeTask(t.id));
  li.appendChild(b);tl.appendChild(li);
 }
 if(!(data.tasks||[]).length)tl.appendChild(el('li','No chores yet.'));
 const rl=$('rules');rl.textContent='';
 for(const r of data.rules||[]){
  const li=el('li');li.setAttribute('data-hook','rule');
  li.appendChild(el('span','No chores on '+DAYS[r.weekday]+'s'));
  const b=el('button','Remove','sec');b.type='button';b.setAttribute('data-hook','rule-remove');b.setAttribute('aria-label','Remove the rule for '+DAYS[r.weekday]);
  b.addEventListener('click',()=>removeRule(r.id));
  li.appendChild(b);rl.appendChild(li);
 }
 $('rempty').hidden=(data.rules||[]).length>0;
}
function fmt0(s){const ms=parse(s);const d=new Date(ms);return DAYS[d.getUTCDay()]+' '+s;}
async function load(){
 const r=await tessera.call('data.read',{});
 data=r.data;rev=r.revisions;
 if(!data.tasks)data.tasks=[];if(!data.rules)data.rules=[];
 render();
}
async function patch(ops){
 try{await tessera.call('data.patch',{operations:ops});await load();return true;}
 catch(e){return false;}
}
async function addTask(){
 const name=$('tname').value.trim();
 $('terr').textContent='';
 if(!name){$('terr').textContent='Type the chore’s name first.';$('tname').focus();return;}
 const ok=await patch([{op:'add',collection:'tasks',record:{name:name,assignee:$('twho').value,weekday:Number($('tday').value)}}]);
 if(ok){$('tname').value='';$('tname').focus();}else $('terr').textContent='Could not save the chore. Your text is still here; try again.';
}
async function addRule(){
 const d=Number($('rday').value);$('rerr').textContent='';
 if(blocked().includes(d)){$('rerr').textContent=DAYS[d]+' is already blocked.';return;}
 if(blocked().length>=6){$('rerr').textContent='At least one weekday must stay open for chores.';return;}
 const ok=await patch([{op:'add',collection:'rules',record:{weekday:d}}]);
 if(!ok)$('rerr').textContent='Could not save the rule. Try again.';
}
async function removeRule(id){
 const ok=await patch([{op:'remove',collection:'rules',id:id,revisionCount:(rev.rules||{})[id]||1}]);
 if(!ok)$('rerr').textContent='Could not remove the rule. Try again.';
}
async function removeTask(id){
 const ok=await patch([{op:'remove',collection:'tasks',id:id,revisionCount:(rev.tasks||{})[id]||1}]);
 if(!ok)$('terr').textContent='Could not remove the chore. Try again.';
}
function fillSelects(){
 for(const n of names()){const o=el('option',n);o.value=n;$('twho').appendChild(o);}
 for(let i=0;i<7;i++){
  const o=el('option',DAYS[i]);o.value=String(i);$('tday').appendChild(o);
  const p=el('option',DAYS[i]);p.value=String(i);$('rday').appendChild(p);
 }
}
$('tadd').addEventListener('click',addTask);
$('tname').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();addTask();}});
$('radd').addEventListener('click',addRule);
(async()=>{
 const c=await tessera.call('clock.now',{});today=c.date;
 await load();
 fillSelects();
 $('tday').value=String(wd(parse(today)));
})();

